-- Source: qeynos/Mespha_Tevalian.lua
-- items: 18720, 13508
function event_spawn(e)
	local xloc = e.self:GetX();
	local yloc = e.self:GetY();
	eq.set_proximity(xloc - 50, xloc + 50, yloc - 50, yloc + 50);
end

function event_enter(e)
	if e.other:HasItem(18720) then
		e.other:Message(MT.Yellow,"As you glance about the room, Mespha Tevalian greets you. 'Why hello there. Are you perhaps a new recruits? If you wish to learn the ways of the Enchanter, read the note in your inventory and hand me your note to start your training.'");
	end
end

function event_say(e)
	if(e.message:findi("hail")) then
		e.self:Say("Greetings.. I am Mespha Tevalian, Master Enchantress of the Hall of Sorcery and the Order of Three. Here, we all study the three circles of magic, and lend our services to citizens of Qeynos. Rumors of an underground group calling themselves the Bloodsabers have recently been spreading throughout the city. It is our duty to help local guards protect Qeynos' citizens from this new evil.");
	end
end

function event_trade(e)
	local item_lib =require("items");
	if(item_lib.check_turn_in(e.trade, {item1 = 18720})) then -- Tattered Note
		e.self:Say("Greetings, " .. e.other:GetName() .. ". Welcome to the Order of Three. You have much to learn. Wear this robe and represent us well.");
		e.other:SummonItem(13508); -- Blue Training Robe*
		e.other:Ding();
		e.other:Faction(342,100,0); -- Order of Three
		e.other:Faction(221,-25,0); -- Bloodsabers
		e.other:Faction(262,15,0); -- Guards of Qeynos
		e.other:Faction(296,-15,0); -- Opal Dark Briar
		e.other:AddEXP(100);
	end
	item_lib.return_items(e.self, e.other, e.trade)
end

-- items: 12743, 12744, 12742
function event_say(e)
	if(e.message:findi("Hail")) then
		e.self:Say("Please do not harm me.  I am not the one who brought the outsiders to our land.  I am innocent and deserve to return to my people.");
	elseif(e.message:findi("What will you trade for the skull of Di Nozok?")) then
		e.self:Say("Ah, doing the bidding of the council are you?  I will only give up the skull for the 2 Ton Warrior Totems held by the goblins of nurga and frogloks of the swamp of no sarrow, the Canopie of Di Nozok held by the goblin Overseer Dlubish, and 400 gold pieces.");
	elseif(e.message:findi("sealed canopic")) then
		e.self:Say("I have heard of such things.  You must have stumbled upon an ancient jar devised by one of my long-dead ancestors.  They were fine craftsmen.  I do not share their gift, but I do know the secret of the locks.  If you have one of the ancient Vok Nir canopics, allow me to open it for you.");
	elseif(e.message:findi("dai keys")) then
		e.self:Say("There are two keys of Dai.  They were made of ceramic and were also crafted to look like warrior totems. I once broke one as a child and my grandfather got very angry.  He lashed me good!  I do not know what the big fuss was about; he easily put them back together using some sort of clay.");
	end
end

function event_trade(e)
	local item_lib = require("items");
	--Turn in the 2 totems and the canopie of Di Nozok and 400 gold pieces
	if(item_lib.check_turn_in(e.trade, {item1 = 12743, item2 = 12744, item3 = 12742, gold = 400})) then
		e.self:Say("A deal is a deal I suppose, many have attempt to do what I have asked, but fallen to the Overseer.");
		e.other:QuestReward(e.self,0,0,0,0,12740); -- Give the player the Iksar Skull
	end
	item_lib.return_items(e.self, e.other, e.trade) --return items if not the ones required
end

function event_death_complete(e)
	eq.signal(201451, 9); -- NPC: #Event_Stoning_Control
end

-- items: 9590
function event_say(e)
	if(e.message:findi("hail")) then
		e.self:Say("Hello " .. e.other:GetName() .. ", Such a beautiful day for music and tales. Don't you think?");
	end
end

function event_trade(e)
	local item_lib = require("items");

	if(item_lib.check_turn_in(e.trade, {item1 = 9590})) then -- Notice to Cease and Desist
		e.self:Say("What's this? It says that you wish me to cease and desist spreading slander about the swashbuckler known as Stanos, or else . . .? You know, I am new in Freeport. Haven't been performing at this venue for long. I'm just a fledgling muse trying to make ends meet in this big city. My father told me that someday I'd have to put up my fists to protect my rights. I can see that day is today. What I have to say to you is . . . Guards, help!");
		e.self:SetSpecialAbility(19, 0);
		e.self:SetSpecialAbility(20, 0);		
		e.self:SetSpecialAbility(24, 0);
		e.self:SetSpecialAbility(25, 0);
		eq.set_timer('gate', 16 * 1000);
		eq.set_timer('guard', 10 * 1000);		
		eq.attack(e.other:GetName());
	end
	item_lib.return_items(e.self, e.other, e.trade)
end

function event_timer(e)
  if (e.timer == 'guard') then
	eq.spawn2(eq.ChooseRandom(382255,382256),0,0,e.self:GetX()-5,e.self:GetY()-5,e.self:GetZ(),e.self:GetHeading()); -- NPC(s): a_Freeport_guard (382255), a_seasoned_Freeport_guard (382256)
		local entity_list = eq.get_entity_list();
		-- aggro guards
		local npc_list = entity_list:GetNPCList();
		for npc in npc_list.entries do
			if (npc.valid and (npc:GetNPCTypeID() == 382255 or  npc:GetNPCTypeID() == 382256)) then
				npc:AddToHateList(e.self:GetHateTop(),1);
			end
		end					

  elseif(e.timer == 'gate') then
  	e.self:GMMove(-873,-1025,11.3,144);
  end
end
-- END of FILE Zone:freporteast -- Lythe_Songbird

-- items: 57919, 52951, 57920
function event_say(e)
	local qglobals = eq.get_qglobals(e.other);	
	if(e.message:findi("hail") and qglobals["ench_epic"] == "9") then 
		e.self:Say("I have been expecting you. There are still a few things more for you to do before the staff is properly prepared. For the next step you will need to travel into Discord and gather two items that I need to perform the next step in the purification process. A great beast by the name of Cipheron has hoarded an incantation for many years. I believe he killed one of our students who was unfortunate enough to get in his way... Reguardless, I will need it. You will also need to gather a noxious secretion from a withering murkglider. It is a strange fluid they begin to secrete as they are dying, and it is very powerful. Bring me this incantation and the secretion and we shall get started.");
	end
end

function event_trade(e)
	local item_lib = require("items");
	local qglobals = eq.get_qglobals(e.other);
	if(qglobals["ench_epic"] == "9" and item_lib.check_turn_in(e.trade, {item1 = 57919,item2 = 52951})) then
		e.self:Emote("murmurs in a strange tongue as she scans the incantation. She draws an intricate design along different portions of the staff, using the strange secretion, from which rises a pale green smoke. At last she stops and opens her eyes. 'Perfect. This tool has been consecrated and protected in the best way I know. There is but one thing left to do, for the staff is ready but not yet tested. Take this channeling crystal and venture into the land riddled with discord. When you encounter great evil there, you will recognize the energy of discord. Channel this energy into your staff, and it will become something more powerful than this world has seen. I wish you luck.");
		e.other:SummonItem(57920); -- Item: Channeling Crystal
	end
	item_lib.return_items(e.self, e.other, e.trade)
end

