-- Source: freportw/Captain_Hazran.lua
-- items: 13916
function event_say(e)
	if(e.message:findi("hail")) then
		e.self:Say("Hail citizen. Welcome to the Freeport Militia House. It is time for you to serve the state. You will assist us with our war with [Clan Deathfist] before you are truly accepted within our city. We urge you to be all we command you to be.");
	elseif(e.message:findi("clan deathfist")) then
		e.self:Say("Clan Deathfist are the orcs of the Commonlands. They are a nuisance and Sir Lucan has ordered their extermination. You will go forthh into the Commonlands and kill these orcs. Clan Deathfits is known to wear a Clan Belt. Bring this belt to me as proof of their death and you shall receive your wages and prove your allegiance to Freeport and all that is good.");
	elseif(e.message:findi("bigger problem")) then
		e.self:Say("The bigger problem is the Knights of Truth. We have already started our campaign to rid the city of the Knights. The so-called Knights of Truth are not to be trusted.");
	end
end

local function reward_belts(e, count)
	e.self:Say("Good work warrior. Your are good Militia material. Beware though, there are some who dare to call us foe. You have performed so well.");
	e.other:Ding();
	e.other:Faction(330,5 * count,0); -- Freeport Militia
	e.other:Faction(362,-1 * count,0); -- Priests of Marr
	e.other:Faction(281,-1 * count,0); -- Knights of Truth
	e.other:Faction(336,1 * count,0); -- Coalition of Tradefolk Underground
	e.other:AddEXP(14000 * count);
	e.other:GiveCash(0,0,3 * count,0);
end

function event_trade(e)
	local item_lib = require("items");

	if(item_lib.check_turn_in(e.trade, {item1 = 13916,item2 = 13916,item3 = 13916,item4 = 13916})) then
		reward_belts(e, 4);
	elseif(item_lib.check_turn_in(e.trade, {item1 = 13916,item2 = 13916,item3 = 13916})) then
		reward_belts(e, 3);
	elseif(item_lib.check_turn_in(e.trade, {item1 = 13916,item2 = 13916})) then
		reward_belts(e, 2);
	elseif(item_lib.check_turn_in(e.trade, {item1 = 13916})) then
		reward_belts(e, 1);
	end
	item_lib.return_items(e.self, e.other, e.trade);
end

-- END of FILE Zone:freportw  ID:9109 -- Captain_Hazran

--Ikkinz Raid #2: Chambers of Glorification
function event_spawn(e)
	eq.set_next_hp_event(50);
end

function event_hp(e)
  if(e.hp_event == 50) then
    e.self:SetSpecialAbility(4, 1); --turn aoe ramp on
    eq.zone_emote(MT.Red,"Visionary of Glory is infuriated!");
    eq.set_next_hp_event(40);
  elseif(e.hp_event == 40) then
    e.self:SetSpecialAbility(4, 0); --turn aoe ramp off
    eq.zone_emote(MT.Red,"Visionary of Glory is no longer infuriated.");
    eq.set_next_hp_event(10);
  elseif(e.hp_event == 10) then
    e.self:SetSpecialAbility(4, 1); --turn aoe ramp on
    eq.zone_emote(MT.Red,"Visionary of Glory is infuriated!");
  end
end

function event_combat(e)
	if e.joined then
		eq.set_timer("OOBcheck", 3 * 1000);

	else
		eq.stop_timer("OOBcheck");
	end
end


function event_timer(e)
if(e.timer=="OOBcheck") then
eq.stop_timer("OOBcheck");
	if (e.self:GetX() < -35 or e.self:GetX() > 120 or e.self:GetY() > -100 or e.self:GetY() < -310) then --($x > 120 || $x < 35 || $y > -100 || $y < -310) {
		e.self:CastSpell(3791,e.self:GetID()); -- Spell: Ocean's Cleansing
		e.self:GotoBind();
		e.self:WipeHateList();
	else
		eq.set_timer("OOBcheck", 3 * 1000);
	end
end
end

-- items: 18817, 18818
function event_say(e)
	if(e.message:findi("hail")) then
		e.self:Say("Greetings, citizen! You should not be in the Militia House. These are restricted grounds. Please leave at once unless you have business here.");
	elseif(e.message:findi("truth is good") and e.other:Class() == "Paladin") then
		e.self:Say("Ssshhh!! Pipe down. The others might hear you. You must have something for me. Kalatrina must have given you something if you serve the Hall of Truth. If you have nothing please leave. You will blow my cover.");
	end
end

function event_trade(e)
	local item_lib = require("items");

	if(e.other:Class() == "Paladin") then
		if(item_lib.check_turn_in(e.trade, {item1 = 18817})) then -- Sealed Letter
			e.self:Say("This is not good news. I must leave immediately. Here. Take this to Kala.. I mean my father. I found it on the floor of Sir Lucan D'Lere's quarters. Thanks again, messenger. I got this just in time.");
			e.other:SummonItem(18818); -- A Tattered Flier
			e.other:Ding();
			e.other:Faction(311,1,0); -- Steel Warriors
			e.other:Faction(262,1,0); -- Guards of Qeynos
			e.other:Faction(230,-1,0); -- Corrupt Guards of Qeynos
			e.other:Faction(330,-1,0); -- Freeport Militia
			e.other:Faction(281,1,0); -- Knights of Truth
			eq.unique_spawn(9143,87,0,-154,-55,-10,256); -- spawns Krazen Loosh
		end
	end
	item_lib.return_items(e.self, e.other, e.trade)
end

function event_signal(e)
	e.self:Say("'Oh no!! It is too late!! Run!!");
	eq.signal(9143,1,30000); -- NPC: Krazen_Loosh
end

-- END of FILE Zone:freportw Guard_Alayle

-- items: 17512, 6710, 17080, 12335, 12338, 12337, 12254
function event_say(e)
	if(e.message:findi("coffin")) then
		e.self:Say("You're looking for a craftsman, are you? Well look no further! For I, Ping Fizzlecutter, am the best in all the lands! Or at lest this side of Freeport. So you're the one that Valeron was talking about, eh? Well, while you were off traipsing around the lands he and I discussed the details of the coffin. I require nothing less than these [components]. Get me them and I will gladly make you a coffin any king would be proud to be buried in!");
	elseif(e.message:findi("components")) then
		e.self:Say("I require a diamond, a star ruby, a pearl, a [special fire emerald], a sapphire, a fire opal, and two enchanted platinum bars. Take this bag and combine the items once you have them all and bring it back to me.");
		-- Empty Gem Bag ID-17512
		e.other:SummonItem(17512); -- Item: Empty Gem Bag
	elseif(e.message:findi("special fire emerald")) then
		e.self:Say("Now the fire emerald I want is not the normal one you receive from most jewelers. There is one jeweler I know who has the special one I want. Last time I heard, she had traveled to the elven outpost. Just ask her about special fire emeralds.");
	elseif(e.message:findi("repair the toupee")) then
		e.self:Say("Ah!! You have a toupee to repair. It must be the [Mane Attraction]. I gave a one out and it seems to always fall to pieces. Seeing as it has a 100 season warranty and I only created it 5 seasons ago, I suppose I can do it. Do you want me to [make the Mane Attraction].");
	elseif(e.message:findi("what is the mane attraction")) then
		e.self:Say("The Mane Attraction is a special toupee I created for a Gnome junker. He wasn't getting much attention at the taverns till I created the eye catching toupee. He became one Charismatic Gnome after that. Unfortunately, it seems to fall to pieces to easy and since it has a warranty, I have to fix it for him every time at no charge!! I will never make another. ");
	elseif(e.message:findi("make the mane attraction")) then
		e.self:Say("If you have the original tattered toupee then I can do it. Before you give it to me I will also need three other items. I require two clumps of hair from a Hulking Gorilla and a strand of hair from a [certain mermaid].");
	elseif(e.message:findi("certain mermaid")) then
		e.self:Say("I encountered a particular mermaid with beautiful hair!! She had beautiful golden tresses. I used a lock of her hair to create the Mane Attraction. That was a while back when I was in Faydwer.");
	end
end

function event_trade(e)
	local item_lib = require("items");

	if(item_lib.check_turn_in(e.trade, {item1 = 6710})) then -- Full Gem Bag
		e.self:Emote("smiles broadly as he rifles through the bag, then looks up at you and says, 'Bout time! Here is the coffin as promised.'");
		e.other:SummonItem(17080); -- Gem Encrusted Casket
		e.other:Ding();
	-- Clumps of Hair ID- 12335 - Lock of Hair ID- 12338 - Tattered Toupee ID- 12337
	elseif(item_lib.check_turn_in(e.trade, {item1 = 12335,item2 = 12335,item3 = 12338,item4 = 12337})) then
		e.self:Say("You are a good helper. Here you go. One genuine, charismatic, lady magnet, zero to hero making Mane Attraction!! Guaranteed to lower prices world wide. Guaranteed to last forever.. Err.. Well,.. It has a 1000 year warranty at least.");
		e.other:SummonItem(12254); -- Item: Mane Attraction
		e.other:Ding();
		e.other:Faction(229,3,0); -- Faction: Coalition of Tradefolk
		e.other:Faction(281,3,0); -- Faction: Knights of Truth
		e.other:Faction(291,3,0); -- Faction: Merchants of Qeynos
		e.other:Faction(336,3,0); -- Faction: Coalition of Tradefolk Underground
		e.other:AddEXP(500);
	end
	item_lib.return_items(e.self, e.other, e.trade)
end

