function event_scale_calc(e)
    local wis = e.owner:GetWIS();
    local agi = e.owner:GetAGI();

    if(wis < 0) then
        wis = 0;
    end

    if(agi < 0) then
        agi = 0;
    end
    local combined_stat = wis + agi;
    lookup(e,combined_stat);
end


