   eq.spawn2( 201469, 0, 0, 1298, -1169, -13, 126 ); -- NPC: #a_flickering_spirit
   eq.spawn2( 201469, 0, 0, 1153, -1119,  88, 126 ); -- NPC: #a_flickering_spirit
