      eq.spawn2( eq.ChooseRandom( 201464, 201465, 201466, 201470, 201465, 201466, 201465, 201466 ), 0, 0, 1378, -1169, 1, 128 );
      eq.spawn2( eq.ChooseRandom( 201464, 201465, 201466, 201470, 201465, 201466, 201465, 201466 ), 0, 0, 1395, -1070, 1, 128 );
      eq.spawn2( eq.ChooseRandom( 201464, 201465, 201466, 201470, 201465, 201466, 201465, 201466 ), 0, 0, 1378, -1070, 1, 128 );

